"""ACQ-R06b §D — every table of the report, generated from the run's JSON files (no typed numbers).

Writes reports_post_grl_review/ACQ-R06b/tables/<name>.md and tables.json.  Usage: python -m src.phase4.tables_r06b
"""
from __future__ import annotations

import json
import re
import sys
from pathlib import Path

import pandas as pd

from src.acq_r04.tables import to_md
from src.acq_r01 import common as C
from src.phase4 import common as P

T = P.REPORT_DIR / "tables"


def md(df: pd.DataFrame, name: str, note: str = "") -> str:
    T.mkdir(parents=True, exist_ok=True)
    df = df.copy()
    for c in df.columns:
        df[c] = df[c].map(lambda v: "yes" if v is True else ("no" if v is False else v))
    txt = (f"<!-- generated by src/phase4/tables_r06b.py from {note} -->\n" if note else "") + to_md(df)
    (T / f"{name}.md").write_text(txt + "\n")
    return txt


def script_hashes() -> pd.DataFrame:
    before = {l.split()[1]: l.split()[0] for l in (P.REPORT_DIR / "sha_before.txt").read_text().splitlines() if l.strip()}
    files = sorted(set(before) | {str(p.relative_to(P.REPO)) for p in (P.REPO / "src/phase4").glob("*.py")} | {"sbatch/acq_r06b/rehearsal.sbatch", "sbatch/acq_r06b/harness.sbatch"})
    summ = {"src/acq_r01/common.py": "assert_no_lockbox_cruise honours the phase4 allowance (the unchanged fetcher asserts it); nothing else",
            "src/phase4/common.py": "ACQ-R06b report dirs; PRIOR_VALUE_DESIGNATION, LOCKBOX_FETCH_SET; June sweep / plan readers; OAK root listing; fixed inputs + acq_r06_rehearsal SHA256SUMS",
            "src/phase4/sealed_step1.py": "A1 prior values by designation + consistency check; A2 fetch trigger, lock 5, fetch_cruise (unchanged fetcher), swath preflight counts, incomplete-fetch branch; A3 write_outputs (recorded, reversed mode change; no overwrite); A4 per-k verdicts + k source in the run record",
            "src/phase4/refusal_tests.py": "tests 10 (trigger set), 11 (confirmatory count), 12 (A1 consistency), 13 (guard afterwards)",
            "src/phase4/harness_r06b.py": "new: B2 fetch rehearsal + failure branch, B3 prior-value rehearsal, B4 write-path rehearsal + blocked write",
            "src/phase4/compare_runs.py": "new: B1 rerun vs ACQ-R06 outputs", "src/phase4/tables_r06b.py": "new: these tables",
            "src/phase4/preserve.py": "--dest-name / --extra-tree arguments", "src/phase4/report.py": "--name argument",
            "sbatch/acq_r06b/rehearsal.sbatch": "new: B1 driver", "sbatch/acq_r06b/harness.sbatch": "new: B2-B4 driver"}
    rows = []
    for f in files:
        p = P.REPO / f
        after = P.sha256_file(p) if p.exists() else "MISSING"
        rows.append({"file": f, "sha256 before": before.get(f, "(new)")[:16], "sha256 after": after[:16], "changed": before.get(f) != after, "summary": summ.get(f, "unchanged") if before.get(f) != after else "unchanged"})
    return pd.DataFrame(rows)


def permissions_code() -> pd.DataFrame:
    """A3.1: the code lines that set modes on the sealed directories and their files (from code only)."""
    rows = []
    for f, pat in (("src/acq_r01/harmonize_new.py", r"mkdir|chmod|lock_dir\("), ("src/harmonize.py", r"mkdir|chmod"), ("src/acq_r01/build_products.py", r"chmod|def write_raster"),
                   ("src/acq_r03/build_products_v2_1.py", r"chmod"), ("src/discovery/stage_f_harmonize.py", r"mkdir|chmod"), ("src/discovery/stage_unify_valid_masks.py", r"RO =|RW =|os\.chmod\(dstm|os\.chmod\(p, RO")):
        for i, line in enumerate((P.REPO / f).read_text().splitlines(), 1):
            if re.search(pat, line) and "tmp" not in line and "qcd" not in line and "processed_crosscheck" not in line:
                rows.append({"file": f, "line": i, "code": line.strip()[:120]})
    return pd.DataFrame(rows)


def main(argv=None):
    run = json.loads((P.REHEARSAL_DIR / "step1_run_rehearsal_r06b.json").read_text())
    cmp = json.loads((P.REHEARSAL_DIR / "compare_r06b_vs_full.json").read_text())
    h = json.loads((P.REPORT_DIR / "harness_r06b.json").read_text())
    ref = json.loads((P.REPORT_DIR / "refusal_tests.json").read_text())
    guard = json.loads((P.REPORT_DIR / "guard_selftest.json").read_text())
    fz_p = P.REPORT_DIR / "freeze_record.json"; fz = json.loads(fz_p.read_text()) if fz_p.exists() else None
    jobs = [l.split() for l in (P.REPORT_DIR / "jobs.txt").read_text().splitlines() if l.strip() and l.split()[1] in ("r06b", "harness")]
    numbers = {"generated": P.utc_now(), "code_commit": P.git_commit(), "jobs": {j[1]: j[0] for j in jobs}, "host": run["host"], "cpu_model": run["cpu_model"],
               "fixed_inputs": run["fixed_input_sha256"], "guard": {"readers_blocked": guard["reader_checks"]["n_blocked"], "readers_n": guard["reader_checks"]["n"], "all_passed": guard["all_passed"], "guard_sha256": guard["guard_sha256"]},
               "refusal": {"n_tests": ref["n_tests"], "n_passed": ref["n_passed"], "all_passed": ref["all_passed"]}}
    # scripts
    sh = script_hashes(); md(sh, "script_hashes", "sha_before.txt + working tree"); numbers["scripts"] = {"n_changed": int(sh.changed.sum()), "changed": sh[sh.changed].file.tolist(),
                                                                                                        "sealed_step1_before": sh[sh.file == "src/phase4/sealed_step1.py"]["sha256 before"].iloc[0], "guard_before": sh[sh.file == "src/acq_r01/common.py"]["sha256 before"].iloc[0]}
    numbers["scripts"]["sealed_step1_after"] = P.sha256_file(P.REPO / "src/phase4/sealed_step1.py"); numbers["scripts"]["guard_after"] = P.sha256_file(P.REPO / "src/acq_r01/common.py")
    # mode branches
    src = (P.REPO / "src/phase4/sealed_step1.py").read_text().splitlines()
    md(pd.DataFrame([{"line": i, "code": l.strip()[:150]} for i, l in enumerate(src, 1) if re.search(r"a\.mode\s*==|MODES\s*=|MODES\[|cfg\[\"mode\"\]|cfg\['mode'\]|\"rehearsal\":|\"phase4\":", l)]), "mode_branches", "src/phase4/sealed_step1.py")
    # B1
    rows = []
    for r in cmp["pairs"]:
        s = r["spacings_k"]; p = r["products"]
        rows.append({"pair_id": r["pair_id"], "hr r06b / r06": f"{s['hr_native_res_m']['r06b']} / {s['hr_native_res_m']['r06']}", "lr r06b / r06": f"{s['lr_native_res_m']['r06b']} / {s['lr_native_res_m']['r06']}",
                     "k r06b / r06": f"{s['max_recoverable_k']['r06b']} / {s['max_recoverable_k']['r06']}", "status": f"{s['status']['r06b']} / {s['status']['r06']}", "per-k verdicts equal": s["per_k"]["equal"],
                     "spacings/k equal": r["spacings_k_equal"], "products": "built" if p.get("all_rasters_bit_identical") is not None else p.get("note"), "rasters bit-identical": p.get("all_rasters_bit_identical"),
                     "QA + flags equal": p.get("qa_all_equal"), "files same": p.get("files_same"), "supplement columns differing": ", ".join(d["column"] for d in r["supplement"]["differing"]) or "none",
                     "dir mode before -> opened -> after": f"{r['write_path']['mode_before']} -> {r['write_path']['mode_opened']} -> {r['write_path']['mode_after']}" if r.get("write_path") else "", "pass": r["pass"]})
    md(pd.DataFrame(rows), "b1_rerun", "rehearsal/compare_r06b_vs_full.json")
    rows = [{"pair_id": r["pair_id"], "column": d["column"], "r06b": d["r06b"][:100], "r06": d["r06"][:100]} for r in cmp["pairs"] for d in r["supplement"]["differing"]]
    md(pd.DataFrame(rows) if rows else pd.DataFrame([{"pair_id": "none"}]), "b1_differing_columns", "rehearsal/compare_r06b_vs_full.json")
    numbers["b1"] = {k: cmp[k] for k in ("n_pairs", "n_pass", "all_pass", "n_spacings_k_equal", "n_products_built", "n_rasters_bit_identical", "n_qa_equal", "differing_columns_union", "wall_s_new", "wall_s_old", "supplement_sha256_new")}
    pp = run["per_pair"]
    md(pd.DataFrame([{"pair_id": k, "k": v["max_recoverable_k"], "status": v["k_sweep_status"], "k source": v["k_source"], "per-k verdicts": "; ".join(f"{a}: {b}" for a, b in (v.get("per_k") or {}).items()) or "none"} for k, v in pp.items()]), "b1_verdicts", "rehearsal/step1_run_rehearsal_r06b.json")
    md(pd.DataFrame(run["ledger"]), "b1_ledger", "rehearsal/step1_run_rehearsal_r06b.json")
    numbers["b1"]["preflight"] = run.get("swath_preflight"); numbers["b1"]["fetch_trigger"] = run.get("fetch_trigger")
    # B2
    b2 = h["b2"]; f = b2["fetch"]; c = b2["compare"]
    md(pd.DataFrame([{"item": "cruise", "value": f["cruise"]}, {"item": "fetcher", "value": f["fetcher"]}, {"item": "files planned / ok / failed", "value": f"{f['n_planned']} / {f['n_ok']} / {f['n_failed']}"},
                     {"item": "complete", "value": f["complete"]}, {"item": "wall s", "value": f["wall_s"]}, {"item": "same 25 names as OAK", "value": c["same_names"]},
                     {"item": "byte-identical to OAK (sha256)", "value": f"{c['n_byte_identical']} / {c['n_fetched']}"}, {"item": "fetch manifest sha256 == OAK manifest", "value": c["manifest_sha_matches_oak_manifest"]},
                     {"item": "files 0444", "value": c["modes_0444"]}, {"item": "SHA256SUMS written", "value": c["sha256sums_present"]},
                     {"item": "scratch fetch deleted", "value": f"{b2['scratch_fetch_deleted']['n_gz_files']} files, {b2['scratch_fetch_deleted']['bytes']} bytes; remaining {b2['scratch_fetch_deleted']['remaining_gz']}"}]), "b2_fetch", "harness_r06b.json:b2")
    fb = b2["failure_branch"]
    md(pd.DataFrame([{"item": "pairs run", "value": ", ".join(fb["pairs_run"])}, {"item": "EW9801 values source", "value": fb["ew9801"]["values_source"]}, {"item": "EW9801 k / source", "value": f"{fb['ew9801']['max_recoverable_k']} / {fb['ew9801']['k_source']}"},
                     {"item": "EW9801 fetch", "value": json.dumps(fb["ew9801"]["fetch"])}, {"item": "EW9801 products / reason", "value": f"{fb['ew9801']['products']} / {fb['ew9801']['products_reason']}"},
                     {"item": "products.json unavailable_reason", "value": fb["products_json_reason"]}, {"item": "EW9801 ship_products_usable", "value": fb["ew9801"]["ship_products_usable"]},
                     {"item": "TN399 continued", "value": json.dumps(fb["tn399_continued"])}, {"item": "pass", "value": fb["pass"]}]), "b2_failure", "harness_r06b.json:b2.failure_branch")
    md(pd.DataFrame([{"rule applied to": "rehearsal pair list (10)", "triggered": json.dumps(b2["trigger_rehearsal_pairs"]) or "{}"}, {"rule applied to": "the five sealed pairs (records + root listing)", "triggered": json.dumps(b2["triggered_phase4_list_records_only"])},
                     {"rule applied to": "every manifest v2.1 row (lockbox rule)", "triggered": json.dumps(b2["trigger_whole_manifest_lockbox_rule"])},
                     {"rule applied to": "every manifest cruise absent from OAK and in the June plan, any designation", "triggered": ", ".join(b2["absent_from_oak_and_in_june_plan_any_designation"])}]), "b2_trigger", "harness_r06b.json:b2")
    numbers["b2"] = {"pass": b2["b2_pass"], "failure_pass": fb["pass"], "n_byte_identical": c["n_byte_identical"], "n_fetched": c["n_fetched"], "complete": f["complete"], "wall_s": f["wall_s"],
                     "trigger_rehearsal": b2["trigger_rehearsal_pairs"], "trigger_sealed": b2["triggered_phase4_list_records_only"], "trigger_any_designation": b2["absent_from_oak_and_in_june_plan_any_designation"],
                     "deleted": b2["scratch_fetch_deleted"], "reason": fb["ew9801"]["products_reason"]}
    # B3
    b3 = h["b3"]; r = b3["rr1506"]
    md(pd.DataFrame([{"quantity": "hr_native_res_m", "step": r["hr_native_res_m"], "manifest row": r["row_hr"]}, {"quantity": "lr_native_res_m", "step": r["lr_native_res_m"], "manifest row": r["row_lr"]},
                     {"quantity": "max_recoverable_k", "step": r["max_recoverable_k"], "manifest row": r["row_k"]}, {"quantity": "k (June record)", "step": r["max_recoverable_k"], "manifest row": r["june_k"]},
                     {"quantity": "per-k verdicts == June record", "step": r["per_k"] == r["june_per_k"], "manifest row": "; ".join(f"{a}: {b}" for a, b in r["june_per_k"].items())},
                     {"quantity": "sweep run", "step": r["swept"], "manifest row": ""}, {"quantity": "values source", "step": r["values_source"], "manifest row": ""}, {"quantity": "products", "step": r["products"], "manifest row": ""},
                     {"quantity": "pass", "step": r["pass"], "manifest row": ""}]), "b3_prior", "harness_r06b.json:b3")
    md(pd.DataFrame([{"pair_id": k, "designation": v["designation"], "manifest lr_native": v["manifest_lr_native_res_m"], "June sweep lr_native": v["june_sweep_lr_native_m"], "precision dp": v["precision_dp"], "equal": v["equal"],
                      "manifest hr_native": v["manifest_hr_native_res_m"], "June k": v["june_k"], "June per-k verdicts": "; ".join(f"{a}: {b}" for a, b in (v["june_per_k"] or {}).items())} for k, v in b3["lockbox_consistency"].items()]), "b3_lockbox_consistency", "harness_r06b.json:b3")
    numbers["b3"] = {"pass": r["pass"], "consistency_pass": b3["lockbox_consistency_pass"], "inconsistent_stop_pass": b3["inconsistent_record_stop"]["pass"], "inconsistent_result": b3["inconsistent_record_stop"]["result"][:200],
                     "lockbox": {k: {"manifest": v["manifest_lr_native_res_m"], "june": v["june_sweep_lr_native_m"], "k": v["june_k"]} for k, v in b3["lockbox_consistency"].items()}}
    # B4
    b4 = h["b4"]; rows = []
    for label in ("as_found_2770", "no_owner_write_0550"):
        x = b4[label]; w = x["write_path"]
        rows.append({"case": label, "dir mode set": x["dir_mode_set"], "before -> opened -> after": f"{w['mode_before']} -> {w['mode_opened']} -> {w['mode_after']}", "restored": w["restored"], "dir mode now": x["dir_mode_now"],
                     "pre-existing files unchanged (sha256 + 0444)": x["pre_existing_unchanged"], "products bit-identical to ACQ-R06": all(v for k, v in x["products_bit_identical_to_r06"].items() if k != "reference"),
                     "new file modes": ", ".join(sorted({v for k, v in x["new_modes"].items() if k != "ship_products_v2_1"})), "ship_products_v2_1 mode": x["new_modes"]["ship_products_v2_1"], "pass": x["pass"]})
    rows.append({"case": "blocked (os.chmod refused)", "dir mode set": "0o2770", "before -> opened -> after": "", "restored": "", "dir mode now": "", "pre-existing files unchanged (sha256 + 0444)": "",
                 "products bit-identical to ACQ-R06": "", "new file modes": "outputs in pair dir: " + ", ".join(b4["blocked"]["outputs_in_pair_dir"]), "ship_products_v2_1 mode": b4["blocked"]["result"][:120], "pass": b4["blocked"]["pass"]})
    md(pd.DataFrame(rows), "b4_write_path", "harness_r06b.json:b4")
    numbers["b4"] = {k: v["pass"] for k, v in b4.items()}
    md(permissions_code(), "permissions_code", "grep of the chain code")
    # refusal tests
    md(pd.DataFrame([{"test": t["test"], "passed": t["passed"], "raised": t["raised"], "message": t["message"][:150]} for t in ref["tests"]]), "refusal_tests", "refusal_tests.json")
    # freeze
    if fz:
        md(pd.DataFrame([{"file": k, "sha256": v} for k, v in fz["files"].items()]), "freeze_files", "freeze_record.json")
        numbers["freeze"] = {"status": fz["status"], "n_files": fz["n_files"], "sealed_step1_sha256": fz["files"]["src/phase4/sealed_step1.py"], "commit": fz["commit"], "mbsystem": fz["mbsystem"],
                             "container_digest": fz["container"]["digest"], "sandbox_tar_sha256": fz["container"]["sandbox_tar_sha256"], "record_sha256": P.sha256_file(fz_p), "files_changed_since_run": fz["files_changed_since_run"]}
    pv = P.REPORT_DIR / "preserve_verify.json"
    if pv.exists():
        numbers["preserve"] = {k: v for k, v in json.loads(pv.read_text()).items() if k in ("destination", "n_files", "n_bad", "bytes", "sha256sums_sha256")}
    numbers["harness_all_passed"] = h["all_passed"]; numbers["harness_wall_s"] = h["wall_s"]
    P.write_json(P.REPORT_DIR / "tables.json", numbers, mode=0o644)
    print(json.dumps({k: v for k, v in numbers.items() if k not in ("fixed_inputs",)}, indent=1, default=str)[:3000])
    return 0


if __name__ == "__main__":
    sys.exit(main())
